const d = msg.payload;
d.received = new Date().toISOString();
flow.set('lastSensor', d);
let h = flow.get('history') || [];
h.push(d);
if (h.length > 50) h.shift();
flow.set('history', h);

const db = context.get('db');
if (db) {
  db.prepare('INSERT INTO sensor (suhu, kelembaban, timestamp, received) VALUES (?, ?, ?, ?)').run(d.suhu, d.kelembaban, d.timestamp || null, d.received);
}

const th = flow.get('threshold') ?? 30;
const panas = d.suhu > th;
const sudah = flow.get('alerted') || false;
const keWs = [{payload: {type: 'sensor', data: d, threshold: th}}];
let keMqtt = null;
if (panas && !sudah) {
  const a = {type: 'alert', message: 'Suhu ' + d.suhu + ' C melewati batas ' + th + ' C', suhu: d.suhu, threshold: th, time: d.received};
  keWs.push({payload: a});
  keMqtt = {topic: 'iot/alert', payload: a};
  node.warn(a.message);
}
flow.set('alerted', panas);
return [keWs, keMqtt];

