try {
  const DB = global.get('DatabaseSync');
  const db = new DB('C:/praktikumiot/iot.db');
  db.exec('PRAGMA journal_mode=WAL');
  db.exec('PRAGMA busy_timeout=2000');
  db.exec('CREATE TABLE IF NOT EXISTS sensor (id INTEGER PRIMARY KEY AUTOINCREMENT, suhu REAL, kelembaban REAL, timestamp TEXT, received TEXT)');
  context.set('db', db);
} catch (e) {
  node.warn('SQLite tidak aktif, pakai memori: ' + e.message);
}

