if (msg.req.headers['x-api-key'] !== 'iot-rafi-2026') {
  msg.statusCode = 401;
  msg.payload = {status: 'error', message: 'API key salah atau kosong'};
  msg.headers = {'Access-Control-Allow-Origin': '*'};
  return [null, msg];
}
return [msg, null];

msg.payload = {
  status: 'success',
  data: flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null},
  threshold: flow.get('threshold') ?? 30,
  server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

let rows;
const db = context.get('db');
if (db) {
  rows = db.prepare('SELECT suhu, kelembaban, timestamp, received FROM sensor ORDER BY id DESC LIMIT 50').all().reverse().map(r => ({...r}));
} else {
  rows = flow.get('history') || [];
}
msg.payload = {status: 'success', source: db ? 'sqlite' : 'memory', count: rows.length, data: rows};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

