const b = msg.payload;
msg.headers = {'Access-Control-Allow-Origin': '*'};
if (!b || !b.device || !b.action) {
  msg.statusCode = 400;
  msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
  return [msg, null];
}
const m = {topic: 'iot/kontrol', payload: b};
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: b};
return [msg, m];

const n = Number(msg.payload && msg.payload.batas);
msg.headers = {'Access-Control-Allow-Origin': '*'};
if (!msg.payload || msg.payload.batas === undefined || !isFinite(n)) {
  msg.statusCode = 400;
  msg.payload = {status: 'error', message: 'batas wajib berupa angka'};
  return msg;
}
flow.set('threshold', n);
flow.set('alerted', false);
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diubah', batas: n};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
